import manifest from './manifest.json';
import { ART_FILES } from './art.gen';
import { glyphName } from './glyphs';
import { resolveArt } from '../artPack/artPack.svelte';

/**
 * Pixel icons (docs/plans/pixel-icons.md). A def names its art with `art`, a
 * name from manifest.json, or leaves it out and takes the drawing the glyph
 * table (glyphs.ts) holds for its emoji; the manifest maps the name to a file under
 * src/assets/, and art.gen.ts (generated by `npm run icons`) holds the URL of
 * every listed file that is on disk. The packs are gitignored, so a checkout
 * without them finds no URL in the bundle; the imported art pack is asked
 * next (artPack/artPack.svelte.ts, key = the manifest's file path), and the
 * icon falls back to the def's emoji when it has neither — the same
 * arrangement enemy portraits use (enemyArt.ts).
 *
 * Core stays browser-free: art never leaves the UI layer.
 */

/** Icon name → file under src/assets/. The only part of the art in git. */
export const ICON_MANIFEST: Record<string, string> = manifest;

const FROM_HERE = '../../../assets/';

/** URL of a manifest icon, or null when the name is unknown or its file is in neither the bundle nor the art pack. */
export function artUrl(name: string | undefined): string | null {
  if (!name) return null;
  const file = ICON_MANIFEST[name];
  return file ? resolveArt(file, ART_FILES[FROM_HERE + file]) : null;
}

/**
 * The manifest name a def draws: its own `art`, else the glyph table's entry
 * for its emoji (glyphs.ts), else none. An empty `art` is absent. Text only,
 * so tests can ask which entries of a registry have art without the packs on
 * disk.
 */
export function artName(def: { icon?: string; art?: string }): string | undefined {
  return def.art || (def.icon ? glyphName(def.icon) : undefined);
}

/**
 * The art for a def, in the plan's resolution order: its own `art`, then the
 * glyph table, then null (the emoji shows). A def that names an `art` never
 * falls through to the table: if that file is missing, the emoji shows.
 */
export function iconUrl(def: { icon?: string; art?: string }): string | null {
  return artUrl(artName(def));
}
